development.solution_text:
$y=f(-x)$ reflects across the $y$-axis: $(x,y)\to(-x,y)$.
$(1,2)\to(-1,2)$ and $(3,0)\to(-3,0)$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[->] (-4.6,0)--(4.6,0) node[right] {$x$};
\draw[->] (0,-3.4)--(0,3.4) node[above] {$y$};
\draw[thick,gray,dashed,<->,domain=-0.5:4.2,smooth,samples=61,variable=\x] plot ({\x},{0.5*\x*\x*\x-3*\x*\x+4.5*\x});
\draw[thick,blue,<->,domain=-4.2:0.5,smooth,samples=61,variable=\x] plot ({\x},{0.5*(-\x)*(-\x)*(-\x)-3*(-\x)*(-\x)+4.5*(-\x)});
\node[gray,right] at (2.9,2.9) {$y=f(x)$};
\node[blue,left] at (-2.9,2.9) {$y=f(-x)$};
\fill[gray] (1,2) circle (1.5pt);
\fill (-1,2) circle (2pt) node[above] {$(-1,2)$};
\fill (-3,0) circle (2pt) node[below left] {$(-3,0)$};
\end{tikzpicture}
[/tikz]

